// Original exact half-tick geometry. All boards use the same -10..+10 unit reference.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function gapRuler(c,plan,caption='Your ruler'){
 const x=h=>30+(h+20)*18,lo=Math.min(c.fromHalf,plan.endHalf),hi=Math.max(c.fromHalf,plan.endHalf),split=plan.split&&lo<0&&hi>0;
 const pieces=[];for(let h=lo;h<hi;h+=c.stepHalf)pieces.push(`<rect data-gap-piece x="${x(h)}" y="118" width="${c.stepHalf*18}" height="26" fill="${split&&h>=0?'#f2d975':'#d2e8f1'}" stroke="#203c53" stroke-width="1.5"/><path d="M${x(h)+2} 141l${c.stepHalf*18-4} -20" stroke="#526775" stroke-width="1"/>`);
 const ticks=Array.from({length:41},(_,i)=>{const h=i-20;return `<path d="M${x(h)} 91v${h%2?5:9}" stroke="#526775"/>`;}).join('');
 const labels=[-20,-10,0,10,20].map(h=>`<text x="${x(h)}" y="80" text-anchor="middle">${h===0?'0':h<0?'−'+Math.abs(h/2):'+'+h/2}</text>`).join('');
 const a=x(c.fromHalf),b=x(c.toHalf),e=x(plan.endHalf),arrow=plan.showMove&&a!==e?`<path d="M${a} 188H${e}" stroke="#203c53" stroke-width="2"/><path d="M${e+(e>a?-8:8)} 183L${e} 188l${e>a?-8:8} 5" fill="none" stroke="#203c53" stroke-width="2"/>`:'';
 return `<figure class="gap-figure"><figcaption>${esc(caption)}</figcaption><svg class="gap-axis" viewBox="0 0 780 ${plan.showMove?206:166}" role="img" aria-label="${esc(caption)}. Start mark A, Finish mark B and ruler end C in separate lanes. Equal ruler pieces."><path d="M30 91H750" stroke="#526775"/>${ticks}${labels}<path d="M${x(0)} 95V150" stroke="#526775" stroke-dasharray="3 4"/>${pieces.join('')}<g data-gap-marker="A"><path d="M${a} 25V116" stroke="#203c53" stroke-dasharray="2 3"/><circle cx="${a}" cy="21" r="12" fill="white" stroke="#203c53" stroke-width="2"/><text x="${a}" y="27" text-anchor="middle">A</text></g><g data-gap-marker="B"><path d="M${b} 56V116" stroke="#203c53" stroke-dasharray="2 3"/><path d="M${b} 36l14 14-14 14-14-14Z" fill="white" stroke="#203c53" stroke-width="2"/><text x="${b}" y="56" text-anchor="middle">B</text></g><g data-gap-marker="C"><path d="M${e-7} 111h14v40h-14" fill="none" stroke="#216a98" stroke-width="3"/><text x="${e}" y="165" text-anchor="middle">C</text></g>${arrow}</svg></figure>`;
}
